import os
import requests

API_KEY = os.environ["BUTTONDOWN_API_KEY"]
BASE = "https://api.buttondown.com/v1/events"
HEADERS = {"Authorization": f"Token {API_KEY}"}

EVENT_TYPES = ["clicked", "opened", "complained"]


def aggregate_events(email_id: str) -> dict[str, int]:
    """Return the total count per event type for one email."""
    counts = {}
    for event_type in EVENT_TYPES:
        response = requests.get(
            BASE,
            headers=HEADERS,
            params={"email_id": email_id, "event_type": event_type},
        )
        response.raise_for_status()
        counts[event_type] = response.json()["count"]
    return counts


if __name__ == "__main__":
    for event_type, total in aggregate_events("EMAIL_ID").items():
        print(f"{event_type}: {total}")

