const API_KEY = process.env.BUTTONDOWN_API_KEY;
const BASE = "https://api.buttondown.com/v1/events";
const EVENT_TYPES = ["clicked", "opened", "complained"];

const aggregateEvents = async (emailId) => {
    const counts = {};
    for (const eventType of EVENT_TYPES) {
        const params = new URLSearchParams({
            email_id: emailId,
            event_type: eventType,
        });
        const response = await fetch(`${BASE}?${params}`, {
            headers: { Authorization: `Token ${API_KEY}` },
        });
        if (!response.ok) {
            throw new Error(`Request failed: ${response.status}`);
        }
        const data = await response.json();
        counts[eventType] = data.count;
    }
    return counts;
};

const counts = await aggregateEvents("EMAIL_ID");
for (const [eventType, total] of Object.entries(counts)) {
    console.log(`${eventType}: ${total}`);
}
